package com.trampolim.api.career;
import java.util.*;import com.trampolim.api.radar.SkillCatalog;import static com.trampolim.api.radar.RadarModel.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;
@RestController public class CareerEligibilityController {
 private final SkillCatalog users;public CareerEligibilityController(SkillCatalog users){this.users=users;}
 public record Check(String regime,Integer age,boolean enrolled,boolean schoolComplete){}
 @GetMapping("/api/public/career/legal-guidance")public Map<String,Object> guidance(){return Map.of("reviewedAt","2026-10-30","notice","Orientação geral. A validação do contrato e das exceções exige análise humana qualificada.","regimes",List.of(Map.of("regime","INTERNSHIP","requirements",List.of("Matrícula e frequência regular","Termo de compromisso e compatibilidade das atividades","Supervisão e seguro, conforme a legislação"),"source","https://www2.camara.leg.br/legin/fed/lei/2008/lei-11788-25-setembro-2008-581200-normaatualizada-pl.html"),Map.of("regime","APPRENTICESHIP","requirements",List.of("Contrato especial e formação técnico-profissional","Regra geral de 14 a menos de 24 anos, com exceções legais","Condições escolares e jornada apropriadas, a validar"),"source","https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-5452-1-maio-1943-415500-normaatualizada-pe.html")));}
 @PostMapping("/api/career/eligibility")public Map<String,Object> check(@AuthenticationPrincipal String email,@RequestBody Check input){users.user(email);if(input==null||!Set.of("EMPLOYMENT","INTERNSHIP","APPRENTICESHIP").contains(Objects.toString(input.regime(),""))||input.age()!=null&&(input.age()<0||input.age()>120))bad("Revise os dados informados.");var alerts=new ArrayList<String>();if(input.regime().equals("INTERNSHIP")&&!input.enrolled())alerts.add("Confira a matrícula e a frequência na instituição de ensino.");if(input.regime().equals("APPRENTICESHIP")&&input.age()!=null&&(input.age()<14||input.age()>=24))alerts.add("A idade está fora da regra geral; eventuais exceções exigem análise humana, sem coleta de diagnóstico aqui.");return Map.of("status","HUMAN_VALIDATION_REQUIRED","automaticEligibility",false,"storedPersonalData",false,"checks",alerts,"notice","Esta consulta não aprova nem rejeita candidatura e não substitui a validação jurídica e educacional.");}
}
